    if (s < 86400) return `${Math.floor(s / 3600)} h ago`;
    if (s < 86400 * 60) return `${Math.floor(s / 86400)} days ago`;
    if (s < 86400 * 730) return `${Math.floor(s / (86400 * 30))} months ago`;
